<?php $source=$course['content'];partial('platform_header',['title'=>$course['title'],'kicker'=>'YOUR LEARNING JOURNEY','symbol'=>'book','subtitle'=>'Follow the outline, save your place and return when you are ready.']); ?>
<div class="platform-grid section"><section class="panel commerce-panel"><h2><?= t('About this course') ?></h2><div class="prose"><?= \Chengyu\Core\Markdown::render($course['description']) ?></div><p class="hint"><?= t('Access source') ?>: <?= e($source['title']) ?></p><a class="btn secondary" href="<?= e(url($source['kind']==='product'?'product':'article',['id'=>$source['id']])) ?>"><?= t($course['allowed']?'Open source content':'Get course access') ?><?= icon('arrow') ?></a></section><section class="panel commerce-panel"><h2><?= t('Lesson outline') ?></h2><ol class="lesson-outline"><?php foreach($course['lessons'] as $i=>$lesson): $allowed=$course['allowed']||(int)$lesson['preview']; ?><li><a <?= $allowed?'href="'.e(url('learn',['id'=>$lesson['id']])).'"':'aria-disabled="true"' ?>><span class="lesson-step"><?= $allowed?str_pad((string)($i+1),2,'0',STR_PAD_LEFT):icon('lock') ?></span><div class="grow"><strong><?= e($lesson['title']) ?></strong><small><?= $lesson['duration_seconds']?(int)ceil($lesson['duration_seconds']/60).' '.t('minutes'):t('Self-paced') ?> &middot; <?= t($lesson['preview']?'Free preview':'Course access required') ?></small></div><?= icon('arrow') ?></a></li><?php endforeach ?></ol><?php if(!$course['lessons']){empty_state('Lessons are being prepared.','book');} ?></section></div>
